import 'package:flutter/material.dart';import '../services/api.dart';import '../services/store.dart';import '../widgets/result.dart';class CoverPage extends StatefulWidget{const CoverPage({super.key});@override State<CoverPage> createState()=>_S();}class _S extends State<CoverPage>{final resume=TextEditingController(text:Store.resume),job=TextEditingController(),company=TextEditingController(),role=TextEditingController(),notes=TextEditingController();String out='';bool busy=false;Future<void> run()async{setState(()=>busy=true);try{final r=await Api.post('/cover-letter/generate',{'resume_text':resume.text,'job_description':job.text,'company':company.text,'role':role.text,'extra':notes.text});out=r['cover_letter'];await Store.log('Cover letter for ${company.text}');}catch(e){out='Error: $e';}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Cover Letter')),body:ListView(padding:const EdgeInsets.all(14),children:[TextField(controller:company,decoration:const InputDecoration(labelText:'Company')),TextField(controller:role,decoration:const InputDecoration(labelText:'Position')),TextField(controller:resume,minLines:4,maxLines:8,decoration:const InputDecoration(labelText:'Resume')),TextField(controller:job,minLines:5,maxLines:10,decoration:const InputDecoration(labelText:'Job description')),TextField(controller:notes,decoration:const InputDecoration(labelText:'Additional notes')),FilledButton(onPressed:busy?null:run,child:const Text('Generate letter')),if(busy)const LinearProgressIndicator(),if(out.isNotEmpty)Result(title:'Cover letter',text:out)]));}
